  (* [comment removed for export] *)
  Hypothesis PNEW : disj a msz sb (kSpaceSize + kPageSize) /\ disj a msz pa kPtrArrayReserve /\ disj a msz T kPageSize /\ disj a msz (a_ctx s) 160
